\leader{286Y}{Further exercises (a)}
%\spheader 286Ya
Show that if $f$ is a square-integrable function on
$\BbbR^r$, where $r\ge 2$, then

\Centerline{$g(y)
=\Bover1{(\sqrt{2\pi})^r}
 \lim_{\alpha_1,\ldots,\alpha_r\to-\infty,
  \beta_1,\ldots,\beta_r\to\infty}
 \int_{a}^{b}e^{-iy\dotproduct x}f(x)dx$}

\noindent is defined in $\Bbb C$ for almost every $y\in\BbbR^r$, and
that $g$ represents the Fourier transform of $f$.
}%end of exercises

\endnotes{

target_text:
\leader{286Y}{Latihan lanjutan (a)}
%\spheader 286Ya
Tunjukkan bahwa jika $f$ adalah fungsi terintegralkan-kuadrat pada
$\BbbR^r$, dengan $r\ge 2$, maka

\Centerline{$g(y)
=\Bover1{(\sqrt{2\pi})^r}
 \lim_{\alpha_1,\ldots,\alpha_r\to-\infty,
  \beta_1,\ldots,\beta_r\to\infty}
 \int_{a}^{b}e^{-iy\dotproduct x}f(x)dx$}

\noindent terdefinisi dalam $\Bbb C$ untuk hampir setiap $y\in\BbbR^r$, dan
bahwa $g$ merepresentasikan transformasi Fourier dari $f$.
}%end of exercises

\endnotes{
